-- Native API ACL and signature contracts; prepared, not executed offline.
BEGIN;
CREATE EXTENSION IF NOT EXISTS pgtap;
SET LOCAL search_path TO public,pgtap,extensions,pg_temp;
SELECT no_plan();
SELECT ok(NOT has_function_privilege('authenticated','public.automation_marketplace_bind_install_initial_v1(uuid,text,uuid,text,jsonb)','EXECUTE'),'web caller cannot invoke initial binding insertion');
SELECT ok(NOT has_function_privilege('service_role','public.automation_marketplace_bind_install_initial_v1(uuid,text,uuid,text,jsonb)','EXECUTE'),'service caller cannot spoof the private install-only binding path');
SELECT has_function('api','automation_asset_create_listing_v1',ARRAY['text','uuid','text','text','text','jsonb','jsonb','jsonb','text','uuid'],'api.automation_asset_create_listing_v1 canonical wrapper');
SELECT ok(has_function_privilege('authenticated','api.automation_asset_create_listing_v1(text,uuid,text,text,text,jsonb,jsonb,jsonb,text,uuid)','EXECUTE'),'authenticated lifecycle grant automation_asset_create_listing_v1');
SELECT ok(NOT has_function_privilege('anon','api.automation_asset_create_listing_v1(text,uuid,text,text,text,jsonb,jsonb,jsonb,text,uuid)','EXECUTE'),'anonymous lifecycle denied automation_asset_create_listing_v1');
SELECT has_function('api','automation_asset_publish_version_v1',ARRAY['uuid','text'],'api.automation_asset_publish_version_v1 canonical wrapper');
SELECT ok(has_function_privilege('authenticated','api.automation_asset_publish_version_v1(uuid,text)','EXECUTE'),'authenticated lifecycle grant automation_asset_publish_version_v1');
SELECT ok(NOT has_function_privilege('anon','api.automation_asset_publish_version_v1(uuid,text)','EXECUTE'),'anonymous lifecycle denied automation_asset_publish_version_v1');
SELECT has_function('api','automation_asset_submit_review_v1',ARRAY['uuid','text'],'api.automation_asset_submit_review_v1 canonical wrapper');
SELECT ok(has_function_privilege('authenticated','api.automation_asset_submit_review_v1(uuid,text)','EXECUTE'),'authenticated lifecycle grant automation_asset_submit_review_v1');
SELECT ok(NOT has_function_privilege('anon','api.automation_asset_submit_review_v1(uuid,text)','EXECUTE'),'anonymous lifecycle denied automation_asset_submit_review_v1');
SELECT has_function('api','automation_asset_review_decide_v1',ARRAY['uuid','text','text'],'api.automation_asset_review_decide_v1 canonical wrapper');
SELECT ok(has_function_privilege('authenticated','api.automation_asset_review_decide_v1(uuid,text,text)','EXECUTE'),'authenticated lifecycle grant automation_asset_review_decide_v1');
SELECT ok(NOT has_function_privilege('anon','api.automation_asset_review_decide_v1(uuid,text,text)','EXECUTE'),'anonymous lifecycle denied automation_asset_review_decide_v1');
SELECT has_function('api','automation_asset_install_v1',ARRAY['uuid','text','uuid','jsonb','jsonb','boolean'],'api.automation_asset_install_v1 canonical wrapper');
SELECT ok(has_function_privilege('authenticated','api.automation_asset_install_v1(uuid,text,uuid,jsonb,jsonb,boolean)','EXECUTE'),'authenticated lifecycle grant automation_asset_install_v1');
SELECT ok(NOT has_function_privilege('anon','api.automation_asset_install_v1(uuid,text,uuid,jsonb,jsonb,boolean)','EXECUTE'),'anonymous lifecycle denied automation_asset_install_v1');
SELECT has_function('api','automation_asset_upgrade_preview_v1',ARRAY['uuid','uuid'],'api.automation_asset_upgrade_preview_v1 canonical wrapper');
SELECT ok(has_function_privilege('authenticated','api.automation_asset_upgrade_preview_v1(uuid,uuid)','EXECUTE'),'authenticated lifecycle grant automation_asset_upgrade_preview_v1');
SELECT ok(NOT has_function_privilege('anon','api.automation_asset_upgrade_preview_v1(uuid,uuid)','EXECUTE'),'anonymous lifecycle denied automation_asset_upgrade_preview_v1');
SELECT has_function('api','automation_asset_upgrade_apply_v1',ARRAY['uuid','uuid'],'api.automation_asset_upgrade_apply_v1 canonical wrapper');
SELECT ok(has_function_privilege('authenticated','api.automation_asset_upgrade_apply_v1(uuid,uuid)','EXECUTE'),'authenticated lifecycle grant automation_asset_upgrade_apply_v1');
SELECT ok(NOT has_function_privilege('anon','api.automation_asset_upgrade_apply_v1(uuid,uuid)','EXECUTE'),'anonymous lifecycle denied automation_asset_upgrade_apply_v1');
SELECT has_function('api','automation_asset_fork_v1',ARRAY['uuid','text'],'api.automation_asset_fork_v1 canonical wrapper');
SELECT ok(has_function_privilege('authenticated','api.automation_asset_fork_v1(uuid,text)','EXECUTE'),'authenticated lifecycle grant automation_asset_fork_v1');
SELECT ok(NOT has_function_privilege('anon','api.automation_asset_fork_v1(uuid,text)','EXECUTE'),'anonymous lifecycle denied automation_asset_fork_v1');
SELECT has_function('api','integration_connection_upsert_v1',ARRAY['uuid','text','uuid','uuid','text','text','text','jsonb','jsonb','jsonb','jsonb','text','boolean','timestamp with time zone'],'api.integration_connection_upsert_v1 canonical wrapper');
SELECT ok(has_function_privilege('authenticated','api.integration_connection_upsert_v1(uuid,text,uuid,uuid,text,text,text,jsonb,jsonb,jsonb,jsonb,text,boolean,timestamp with time zone)','EXECUTE'),'authenticated lifecycle grant integration_connection_upsert_v1');
SELECT ok(NOT has_function_privilege('anon','api.integration_connection_upsert_v1(uuid,text,uuid,uuid,text,text,text,jsonb,jsonb,jsonb,jsonb,text,boolean,timestamp with time zone)','EXECUTE'),'anonymous lifecycle denied integration_connection_upsert_v1');
SELECT has_function('api','integration_connection_test_v1',ARRAY['uuid'],'api.integration_connection_test_v1 canonical wrapper');
SELECT ok(has_function_privilege('authenticated','api.integration_connection_test_v1(uuid)','EXECUTE'),'authenticated lifecycle grant integration_connection_test_v1');
SELECT ok(NOT has_function_privilege('anon','api.integration_connection_test_v1(uuid)','EXECUTE'),'anonymous lifecycle denied integration_connection_test_v1');
SELECT has_function('api','integration_connection_rotate_v1',ARRAY['uuid','jsonb','boolean','timestamp with time zone'],'api.integration_connection_rotate_v1 canonical wrapper');
SELECT ok(has_function_privilege('authenticated','api.integration_connection_rotate_v1(uuid,jsonb,boolean,timestamp with time zone)','EXECUTE'),'authenticated lifecycle grant integration_connection_rotate_v1');
SELECT ok(NOT has_function_privilege('anon','api.integration_connection_rotate_v1(uuid,jsonb,boolean,timestamp with time zone)','EXECUTE'),'anonymous lifecycle denied integration_connection_rotate_v1');
SELECT has_function('api','integration_connection_revoke_v1',ARRAY['uuid','text'],'api.integration_connection_revoke_v1 canonical wrapper');
SELECT ok(has_function_privilege('authenticated','api.integration_connection_revoke_v1(uuid,text)','EXECUTE'),'authenticated lifecycle grant integration_connection_revoke_v1');
SELECT ok(NOT has_function_privilege('anon','api.integration_connection_revoke_v1(uuid,text)','EXECUTE'),'anonymous lifecycle denied integration_connection_revoke_v1');
SELECT has_function('api','integration_connection_bind_install_v1',ARRAY['uuid','text','uuid','text','jsonb'],'api.integration_connection_bind_install_v1 canonical wrapper');
SELECT ok(has_function_privilege('authenticated','api.integration_connection_bind_install_v1(uuid,text,uuid,text,jsonb)','EXECUTE'),'authenticated lifecycle grant integration_connection_bind_install_v1');
SELECT ok(NOT has_function_privilege('anon','api.integration_connection_bind_install_v1(uuid,text,uuid,text,jsonb)','EXECUTE'),'anonymous lifecycle denied integration_connection_bind_install_v1');
SELECT ok(NOT EXISTS(SELECT 1 FROM pg_proc p JOIN pg_namespace n ON n.oid=p.pronamespace WHERE n.nspname IN ('public','api') AND p.proname IN ('automation_marketplace_get_connection_secret_payload_v1','integration_connection_record_oauth_result_v1')),'no generic getter or unbound OAuth result setter is restored');
SELECT ok(NOT EXISTS(SELECT 1 FROM pg_proc p JOIN pg_namespace n ON n.oid=p.pronamespace WHERE n.nspname='api' AND p.proname=ANY(ARRAY['automation_asset_create_listing_v1','automation_asset_publish_version_v1','automation_asset_submit_review_v1','automation_asset_review_decide_v1','automation_asset_install_v1','automation_asset_upgrade_preview_v1','automation_asset_upgrade_apply_v1','automation_asset_fork_v1','integration_connection_upsert_v1','integration_connection_test_v1','integration_connection_rotate_v1','integration_connection_revoke_v1','integration_connection_bind_install_v1']) AND p.prosecdef),'API lifecycle wrappers remain invokers');
SELECT * FROM finish();
ROLLBACK;
